"use client";

import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";

const items = ["Next.js", "SvelteKit", "Nuxt", "Remix", "Astro", "Vite"];

export function ComboboxTailwind() {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const results = items.filter((i) => i.toLowerCase().includes(query.toLowerCase()));
  const pick = (v: string) => { setQuery(v); setOpen(false); };
  const onKey = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") { e.preventDefault(); setOpen(true); setActive((a) => (a + 1) % Math.max(1, results.length)); }
    if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (a <= 0 ? results.length - 1 : a - 1)); }
    if (e.key === "Enter" && open && results[active]) { e.preventDefault(); pick(results[active]); }
    if (e.key === "Escape") setOpen(false);
  };
  return (
    <div className="relative w-72 text-sm text-zinc-100">
      <input role="combobox" aria-autocomplete="list" aria-expanded={open} aria-controls="cb-list" aria-activedescendant={open && results[active] ? `cb-${active}` : undefined} value={query} placeholder="Search frameworks…" onChange={(e) => { setQuery(e.target.value); setActive(0); setOpen(true); }} onKeyDown={onKey} onBlur={() => setOpen(false)} className="h-9 w-full rounded-lg border border-zinc-800 bg-zinc-900 px-3 outline-none placeholder:text-zinc-500 focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/20" />
      <AnimatePresence>
        {open && (
          <motion.div initial={{ opacity: 0, scale: 0.96, y: -6 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.16 }} className="absolute inset-x-0 top-11 z-50 origin-top rounded-xl border border-zinc-800 bg-zinc-900 p-1 shadow-xl">
            <ul id="cb-list" role="listbox">
              {results.map((r, i) => (
                <li key={r} id={`cb-${i}`} role="option" aria-selected={r === query} onPointerDown={(e) => e.preventDefault()} onClick={() => pick(r)} className={`cursor-pointer rounded-md px-2 py-1.5 ${i === active ? "bg-zinc-800" : ""}`}>{r}</li>
              ))}
            </ul>
            {results.length === 0 && <p role="status" className="py-5 text-center text-zinc-400">No framework found.</p>}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
